import json
from collections import Counter

grid = [[int(x) for x in line.split()] for line in group_text.strip().split('\n')]
h, w = len(grid), len(grid[0])

# For each group mod 10, compute the mode
group_modes = {}
for i in range(h):
    grp = i % 10
    if grp not in group_modes:
        group_modes[grp] = []
    group_modes[grp].append(grid[i])

mode_map = {}
for grp, rows in group_modes.items():
    modes = [Counter(row).most_common(1)[0][0] for row in rows]
    # Mode of modes
    mode_map[grp] = Counter(modes).most_common(1)[0][0]

print("Mode map per group:")
for g in range(10):
    print(f"  Group {g}: {mode_map[g]}")

# Build output
output = []
for i in range(h):
    row_color = mode_map[i % 10]
    output.append([row_color] * w)

print(f"\nOutput first 10 rows:")
for i in range(10):
    print([output[i][0]] * 5, "...", end=" ")
print()

subj = {"action": "submit", "grid": output}
print(json.dumps(subj))
